import json,pathlib,nbformat
from nbclient import NotebookClient
root=pathlib.Path('/private/tmp/kuch02round/student')
answers={a['task']:a['code'] for a in map(json.loads,(root/'work/11-sql-project.jsonl').read_text().splitlines()) if 'task' in a}
load=answers['p-tables'].split('sizes=')[0]
def body(task):return answers[task][len(load):]
cells=[]
def md(s):cells.append(nbformat.v4.new_markdown_cell(s))
def code(s):cells.append(nbformat.v4.new_code_cell(s))
md('# Карта гостя и акции «Зерна»: март–август 2026\n\nСамостоятельный SQL-отчёт для руководителя. Пять вопросов: динамика городов, непродающееся меню, чек карты, возвращаемость приложения и кассы, акционные позиции и маржа. Данные описательные; для измерения воздействия карты или акции потребуется контрольная группа. Для запуска: блокнот в папке рядом с data/, шесть zdb_*.csv в data/, Python с pandas, duckdb, matplotlib и IPython. Все расчёты ниже выполняются с чистого ядра.')
code('import sys\nfrom pathlib import Path\nimport duckdb\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom IPython.display import display,Markdown\nDATA=Path("../data")\nprint("Python",sys.version.split()[0],"pandas",pd.__version__,"DuckDB",duckdb.__version__)\n'+load.replace('t=pd.read_csv(f"zdb_{name}.csv"','t=pd.read_csv(DATA/f"zdb_{name}.csv"'))
md('## 1. Данные, зерно и качество\n\nshops и menu — уникальные справочники кофеен и позиций, guests — регистрации, promos — периоды акций. orders — одна шапка заказа; items — его позиции, ключ order_id+item_id. Выручка = qty×фактическая цена; сумма позиций до одного заказа нужна до среднего чека. NULL guest_id означает отсутствие карты, NULL promo_id — отсутствие акции.')
code(body('p-tables')+'\nprint(sizes,"Заказы без позиций:",empty_orders)\nchecks_quality=duckdb.sql("SELECT COUNT(*) AS joined_lines,COUNT(DISTINCT o.order_id) AS orders_n,COUNT(s.shop_id) AS shop_matches,COUNT(m.item_id) AS menu_matches FROM items i LEFT JOIN orders o USING(order_id) LEFT JOIN shops s USING(shop_id) LEFT JOIN menu m USING(item_id)").df()\ndisplay(checks_quality)\nfor table,key in [("orders","order_id"),("shops","shop_id"),("menu","item_id"),("guests","guest_id"),("promos","promo_id")]:\n    n,unique,nonnull=duckdb.sql(f"SELECT COUNT(*),COUNT(DISTINCT {key}),COUNT({key}) FROM {table}").fetchone()\n    assert n==unique==nonnull\nassert int(checks_quality["joined_lines"].iloc[0])==sizes["items"]\nassert int(checks_quality["shop_matches"].iloc[0])==sizes["items"]\nassert int(checks_quality["menu_matches"].iloc[0])==sizes["items"]\nassert int(checks_quality["orders_n"].iloc[0])==sizes["orders"]\nassert empty_orders==0\nmissing_guest=duckdb.sql("SELECT COUNT(*) FROM orders o LEFT JOIN guests g USING(guest_id) WHERE o.guest_id IS NOT NULL AND g.guest_id IS NULL").fetchone()[0]\nassert missing_guest==0\ndisplay(Markdown(f"**Вывод качества.** Загружены {sizes}; {empty_orders} заказов без позиций, {missing_guest} неизвестных непустых guest_id. Соединение фактов со справочниками сохранило {sizes[\'items\']} строк позиций и все {sizes[\'orders\']} заказов. Ключи справочников обязательны и уникальны. Удаление строк не потребовалось; дальнейшие COUNT и AVG используют нужное зерно."))')
md('## 2. Выручка городов и доля карты')
code(body('p-city-month')+'\ncard_month=duckdb.sql("SELECT date_trunc(\'month\',ordered_at) AS month,COUNT(*) AS orders,ROUND(100*AVG(CASE WHEN guest_id IS NOT NULL THEN 1 ELSE 0 END),1) AS card_pct FROM orders GROUP BY month ORDER BY month").df()\ndisplay(city_month,card_month)\nwide=city_month.pivot(index="month",columns="city",values="revenue")/1000\nax=wide.plot(marker="o",figsize=(9,4))\nax.set_title("Выручка городов за март–август 2026")\nax.set_xlabel("Месяц")\nax.set_ylabel("тыс. ₽")\nplt.show()\nnet=city_month.groupby("month")["revenue"].sum()\ndisplay(Markdown(f"**Вывод.** Выручка полугодия {net.sum():,.0f} ₽, март {net.iloc[0]:,.0f} ₽, август {net.iloc[-1]:,.0f} ₽. Лидер августа — {best_city}. Доля заказов с картой меняется с {card_month[\'card_pct\'].iloc[0]:.1f}% до {card_month[\'card_pct\'].iloc[-1]:.1f}%. Это совместная динамика; слабый март нельзя объяснить только картой: меняется и число заказов, сезон, время после запуска."))')
md('## 3. Непродающееся меню')
code(body('p-unsold')+'\ndisplay(Markdown(f"**Вывод.** Ни разу не продавались {unsold}; первая продажа лимонада {lemonade_first}. Отсутствие продаж — не автоматический повод удалять позицию: возможны плановый запуск, недоступность или ошибка справочника. Вопрос менеджеру: с какой даты эти позиции фактически были доступны и были ли ограничения наличия?"))')
md('## 4. Карта: чек по каналам')
code(body('p-checks')+'\ndisplay(checks)\nax=checks.pivot(index="channel",columns="card",values="avg_check").plot(kind="bar",figsize=(8,4))\nax.set_title("Средний чек заказа по каналам и наличию карты")\nax.set_xlabel("Канал")\nax.set_ylabel("₽ на заказ")\nplt.show()\ndisplay(Markdown(f"**Вывод.** Чек с картой относительно без карты: {diff_pct:+.1f}%. Общие средние: с картой {a.loc[True]:.1f} ₽, без {a.loc[False]:.1f} ₽. Сходство общих средних не обещает неизменность чека после выдачи карты: гости и каналы различаются, а индивидуальное изменение не измерялось. Частоту для гостей без карты сравнить нельзя — идентификатора человека нет."))')
md('## 5. Приложение и касса: регистрация, возврат, удержание')
code(body('p-ghosts')+'\n'+body('p-second')+'\n'+body('p-cohorts')+'\n'+body('p-cohort-source')+'\ndisplay(ghosts,second,ret_src)\nret_wide=ret.pivot(index="cohort",columns="k",values="pct")\ndisplay(ret_wide)\nax=ret_src.set_index("source")[["m1","m2"]].T.plot(marker="o",figsize=(7,4))\nax.set_xticks([0,1],["k=1","k=2"])\nax.set_title("Удержание источников: когорты марта–июня")\nax.set_xlabel("Месяц после первого заказа")\nax.set_ylabel("% гостей исходной когорты")\nplt.show()\napp=ghosts.set_index("source").loc["приложение"]\ndisplay(Markdown(f"**Вывод.** В приложении {int(app[\'no_orders\'])} регистраций без заказа ({app[\'pct\']:.1f}%). Возврат за 30 дней рассчитан только для первого заказа до августа: {second.to_dict(orient=\'records\')}. Удержание мартовской когорты k=1 — {march_m1:.1f}%; разница приложения и кассы на k=2 среди сопоставимых когорт {m2_gap:+.1f} п.п. Правые клетки поздних когорт — не наблюдались, а не нулевые. Разницу источников нельзя считать эффектом канала привлечения: аудитории изначально различаются."))')
md('## 6. Акционные позиции и маржа')
code(body('p-margin')+'\n'+body('p-promo')+'\npromo_items["Акция"]=((promo_items["name"]=="Раф") & (promo_items["month"].dt.month==4)) | ((promo_items["name"]=="Лимонад") & promo_items["month"].dt.month.isin([7,8]))\ndisplay(promo_items,margin)\nax=promo_items.pivot(index="month",columns="name",values="cups").plot(marker="o",figsize=(8,4))\nax.set_title("Продажи рафа и лимонада по месяцам")\nax.set_xlabel("Месяц")\nax.set_ylabel("Чашки / штуки")\nplt.show()\nraff=promo_items[(promo_items["name"]=="Раф") & (promo_items["month"].dt.month==4)].iloc[0]\ndisplay(Markdown(f"**Вывод.** В апреле рафа продано {raff[\'cups\']:.0f}, рост к марту {raff[\'growth_pct\']:+.1f}%. Маржинальность категорий: {dict(zip(margin[\'category\'],margin[\'margin_pct\']))}. Считаю по фактической цене после скидки; июньская скидка приложения не ограничена одной позицией. Изменения продаж во время акции совпадают с сезоном, поэтому это не доказанный эффект. Предлагаю случайно назначать предложение акции сопоставимым гостям и сравнить выручку и маржу на участника с контролем, включая замещение других покупок."))')
md('## 7. Рекомендации руководителю')
code('display(Markdown(f"**Что сделали:** изучили {sizes[\'orders\']} заказов и {sizes[\'items\']} позиций шести таблиц за март–август. **Что нашли:** (1) выручка {net.sum():,.0f} ₽; (2) августовский лидер {best_city}; (3) непроданных позиций {len(unsold)}: {unsold}; (4) общий разрыв чека карты {diff_pct:+.1f}%; (5) у приложения {int(app[\'no_orders\'])} некупивших регистраций; (6) разрыв k=2 {m2_gap:+.1f} п.п.; (7) апрельский рост рафа {raff[\'growth_pct\']:+.1f}%. **Что предлагаем:** выяснить доступность непроданных позиций у менеджера, улучшить переход регистрации приложения в первый заказ, оценивать затраты удержания вместе с маржой и проверить акции контролируемым экспериментом. Превосходство наблюдаемого источника не задаёт отдачу дополнительных вложений."))\nduckdb.sql("CHECKPOINT")')
nb=nbformat.v4.new_notebook(cells=cells,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}})
p=root/'work/zerno-sql.ipynb';nbformat.write(nb,p)
NotebookClient(nb,timeout=180,kernel_name='python3',resources={'metadata':{'path':str(root/'work')}}).execute()
nbformat.write(nb,p)
print('Executed',len(cells),'cells',p)
